"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7499],{47499:e=>{e.exports=JSON.parse('{"slug":"inflyaciya-ssha-pce-avgust-stavka-frs","locale":"ru","title":"\u0418\u043d\u0444\u043b\u044f\u0446\u0438\u044f \u0432 \u0421\u0428\u0410 \u0432 \u0430\u0432\u0433\u0443\u0441\u0442\u0435 \u043e\u043a\u0430\u0437\u0430\u043b\u0430\u0441\u044c \u043d\u0438\u0436\u0435 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0430, \u043d\u043e \u0447\u0430\u0441\u0442\u044c \u0437\u0430\u043c\u0435\u0434\u043b\u0435\u043d\u0438\u044f \u0434\u0430\u043b \u043f\u0435\u0440\u0435\u0441\u0447\u0451\u0442 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0438","description":"\u0418\u043d\u0444\u043b\u044f\u0446\u0438\u044f \u0432 \u0421\u0428\u0410 \u0432 \u0430\u0432\u0433\u0443\u0441\u0442\u0435 3,4% \u043f\u0440\u0438 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0435 3,7%. \u0421\u0442\u0430\u0432\u043a\u0443 \u0424\u0420\u0421 \u043d\u0435 \u0441\u043d\u0438\u0436\u0430\u0435\u0442, \u0440\u044b\u043d\u043e\u043a \u043b\u0438\u0448\u044c \u043c\u0435\u043d\u044c\u0448\u0435 \u0436\u0434\u0451\u0442 \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044f \u0432 \u043e\u043a\u0442\u044f\u0431\u0440\u0435: \u0448\u0430\u043d\u0441 35%. \u041f\u043e\u0447\u0435\u043c\u0443 \u0447\u0430\u0441\u0442\u044c \u0437\u0430\u043c\u0435\u0434\u043b\u0435\u043d\u0438\u044f \u0434\u0430\u043b \u043f\u0435\u0440\u0435\u0441\u0447\u0451\u0442 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0438.","blocks":[{"id":"b001","kind":"paragraph","text":"\u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438 \u0421\u0428\u0410 30 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u044f 2026 \u0433\u043e\u0434\u0430 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043b\u043e \u0434\u0430\u043d\u043d\u044b\u0435 \u043e\u0431 \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u0438 \u0437\u0430 \u0430\u0432\u0433\u0443\u0441\u0442. \u0426\u0435\u043d\u044b \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u043d\u0430 3,4% \u0437\u0430 \u0433\u043e\u0434, \u0445\u043e\u0442\u044f \u0436\u0434\u0430\u043b\u0438 3,7%. \u0411\u0435\u0437 \u0435\u0434\u044b \u0438 \u044d\u043d\u0435\u0440\u0433\u0438\u0438, \u0446\u0435\u043d\u044b \u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0441\u0438\u043b\u044c\u043d\u043e \u0441\u043a\u0430\u0447\u0443\u0442, \u0440\u043e\u0441\u0442 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b 3% \u043f\u0440\u0438 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0435 3,3%. \u042d\u0442\u043e\u0442 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044c \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f PCE, \u043d\u0430 \u043d\u0435\u0433\u043e \u0432 \u043f\u0435\u0440\u0432\u0443\u044e \u043e\u0447\u0435\u0440\u0435\u0434\u044c \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u0424\u0435\u0434\u0435\u0440\u0430\u043b\u044c\u043d\u0430\u044f \u0440\u0435\u0437\u0435\u0440\u0432\u043d\u0430\u044f \u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u0421\u0428\u0410, \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0439 \u0446\u0435\u043d\u0442\u0440\u043e\u0431\u0430\u043d\u043a. \u0415\u0451 \u0446\u0435\u043b\u044c 2%."},{"id":"b002","kind":"paragraph","text":"\u0426\u0438\u0444\u0440\u0430 \u0441\u0440\u0430\u0437\u0443 \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0430 \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u044f \u0440\u044b\u043d\u043a\u0430. \u0412 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 \u0424\u0420\u0421 \u043f\u043e\u0434\u043d\u044f\u043b\u0430 \u0441\u0442\u0430\u0432\u043a\u0443 \u0432\u043f\u0435\u0440\u0432\u044b\u0435 \u0441 2023 \u0433\u043e\u0434\u0430, \u0434\u043e 3,75–4%. \u041f\u043e\u0441\u043b\u0435 \u043d\u043e\u0432\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 \u0448\u0430\u043d\u0441 \u0435\u0449\u0451 \u043e\u0434\u043d\u043e\u0433\u043e \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044f \u043d\u0430 \u0437\u0430\u0441\u0435\u0434\u0430\u043d\u0438\u0438 27–28 \u043e\u043a\u0442\u044f\u0431\u0440\u044f \u0443\u043f\u0430\u043b \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0441 45% \u0434\u043e 35%. \u042d\u0442\u043e \u043d\u0435 \u043f\u043e\u0432\u043e\u0440\u043e\u0442 \u043a \u0434\u0435\u0448\u0451\u0432\u044b\u043c \u0434\u0435\u043d\u044c\u0433\u0430\u043c: \u0441\u043d\u0438\u0436\u0430\u0442\u044c \u0441\u0442\u0430\u0432\u043a\u0443 \u0424\u0420\u0421 \u043d\u0435 \u0441\u043e\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u0438 \u043d\u0435 \u043e\u0431\u0435\u0449\u0430\u0435\u0442. \u0420\u044b\u043d\u043e\u043a \u043f\u0440\u043e\u0441\u0442\u043e \u043c\u0435\u043d\u044c\u0448\u0435 \u0443\u0432\u0435\u0440\u0435\u043d, \u0447\u0442\u043e \u0435\u0451 \u043f\u043e\u0434\u043d\u0438\u043c\u0443\u0442 \u0435\u0449\u0451 \u0440\u0430\u0437."},{"id":"b003","kind":"paragraph","text":"\u041d\u043e \u0437\u0430\u043c\u0435\u0434\u043b\u0435\u043d\u0438\u0435 \u0431\u0435\u0437 \u0435\u0434\u044b \u0438 \u044d\u043d\u0435\u0440\u0433\u0438\u0438 \u043d\u0430\u0440\u0438\u0441\u043e\u0432\u0430\u043b\u0430 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430. \u0411\u044e\u0440\u043e \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u0421\u0428\u0410 \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u043e \u0440\u0430\u0441\u0447\u0451\u0442 \u0446\u0435\u043d \u043d\u0430 \u044e\u0440\u0438\u0434\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0443\u0441\u043b\u0443\u0433\u0438, \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b \u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u044f\u043c\u0438 \u0438 \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u0430\u043b\u043e \u043f\u043e \u043d\u043e\u0432\u043e\u0439 \u043c\u0435\u0442\u043e\u0434\u0438\u043a\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u0441 2021 \u0433\u043e\u0434\u0430. \u042d\u0442\u043e \u043f\u043e\u0445\u043e\u0436\u0435 \u043d\u0430 \u043c\u0430\u0433\u0430\u0437\u0438\u043d, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0441\u043c\u0435\u043d\u0438\u043b \u0432\u0435\u0441\u044b \u0438 \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u0430\u043b \u0441\u0442\u0430\u0440\u044b\u0435 \u0447\u0435\u043a\u0438: \xab\u043f\u043e\u0434\u0435\u0448\u0435\u0432\u0435\u043b\u043e\xbb, \u0445\u043e\u0442\u044f \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044c \u043f\u043b\u0430\u0442\u0438\u0442 \u0441\u0442\u043e\u043b\u044c\u043a\u043e \u0436\u0435. \u0422\u0430\u043a\u043e\u0439 \u043f\u0435\u0440\u0435\u0441\u043c\u043e\u0442\u0440 \u0437\u0430\u0434\u043d\u0438\u043c \u0447\u0438\u0441\u043b\u043e\u043c \u043d\u0430\u0437\u044b\u0432\u0430\u044e\u0442 \u0440\u0435\u0432\u0438\u0437\u0438\u0435\u0439. \u0420\u0435\u0432\u0438\u0437\u0438\u044f \u0441\u043d\u0438\u0437\u0438\u043b\u0430 \u0438\u044e\u043b\u044c\u0441\u043a\u0443\u044e \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u044e \u0431\u0435\u0437 \u0435\u0434\u044b \u0438 \u044d\u043d\u0435\u0440\u0433\u0438\u0438 \u043d\u0430 0,36 \u043f\u0443\u043d\u043a\u0442\u0430, \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0441 3,3% \u0434\u043e 3%. \u0417\u043d\u0430\u0447\u0438\u0442, \u0432 \u0430\u0432\u0433\u0443\u0441\u0442\u0435 \u043e\u043d\u0430 \u043d\u0435 \u0443\u043f\u0430\u043b\u0430, \u0430 \u043e\u0441\u0442\u0430\u043b\u0430\u0441\u044c \u043d\u0430 \u043c\u0435\u0441\u0442\u0435."},{"id":"b004","kind":"paragraph","text":"\u042d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 \u0421\u0428\u0410 \u043f\u0440\u0438 \u044d\u0442\u043e\u043c \u043d\u0435 \u0442\u043e\u0440\u043c\u043e\u0437\u0438\u0442. \u0420\u043e\u0441\u0442 \u0412\u0412\u041f \u0432\u043e \u0432\u0442\u043e\u0440\u043e\u043c \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435 2026 \u0433\u043e\u0434\u0430 \u043f\u0435\u0440\u0435\u0441\u043c\u043e\u0442\u0440\u0435\u043b\u0438 \u0441 1,5% \u0434\u043e 2,2%, \u0440\u0430\u0441\u0445\u043e\u0434\u044b \u043b\u044e\u0434\u0435\u0439 \u0432 \u0430\u0432\u0433\u0443\u0441\u0442\u0435 \u0440\u043e\u0441\u043b\u0438 \u0431\u044b\u0441\u0442\u0440\u0435\u0435 \u0432\u0441\u0435\u0433\u043e \u0437\u0430 \u0433\u043e\u0434. \u041f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u0424\u0435\u0434\u0435\u0440\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0440\u0435\u0437\u0435\u0440\u0432\u043d\u043e\u0433\u043e \u0431\u0430\u043d\u043a\u0430 \u041c\u0438\u043d\u043d\u0435\u0430\u043f\u043e\u043b\u0438\u0441\u0430 \u041d\u0438\u043b \u041a\u0430\u0448\u043a\u0430\u0440\u0438 \u0441\u043a\u0430\u0437\u0430\u043b, \u0447\u0442\u043e \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u044f \u043e\u043a\u043e\u043b\u043e 3% \xab\u0432\u0441\u0451 \u0435\u0449\u0451 \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0432\u044b\u0441\u043e\u043a\u0430\u044f\xbb \u0438 \u0434\u0435\u0440\u0436\u0438\u0442\u0441\u044f \u0432\u044b\u0448\u0435 \u0446\u0435\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 5 \u043b\u0435\u0442. \u0421\u0432\u0435\u0436\u0438\u0435 \u0434\u0430\u043d\u043d\u044b\u0435, \u043f\u043e \u0435\u0433\u043e \u0441\u043b\u043e\u0432\u0430\u043c, \u044d\u0442\u0443 \u043a\u0430\u0440\u0442\u0438\u043d\u0443 \u043f\u043e\u0447\u0442\u0438 \u043d\u0435 \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0438."},{"id":"b005","kind":"paragraph","text":"\u041f\u043e\u044d\u0442\u043e\u043c\u0443 \u043a\u0440\u0435\u0434\u0438\u0442\u044b \u0432 \u0421\u0428\u0410 \u043d\u0435 \u043f\u043e\u0434\u0435\u0448\u0435\u0432\u0435\u043b\u0438. \u0414\u043e\u0445\u043e\u0434\u043d\u043e\u0441\u0442\u044c 10-\u043b\u0435\u0442\u043d\u0438\u0445 \u043e\u0431\u043b\u0438\u0433\u0430\u0446\u0438\u0439 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u0421\u0428\u0410 \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0434\u043e 5,3%, \u0430 \u043e\u0442 \u043d\u0435\u0451 \u0441\u0447\u0438\u0442\u0430\u044e\u0442 \u0438\u043f\u043e\u0442\u0435\u043a\u0443. \u0414\u043b\u044f \u0420\u043e\u0441\u0441\u0438\u0438 \u043d\u043e\u0432\u043e\u0441\u0442\u044c \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0447\u0435\u0440\u0435\u0437 \u0434\u043e\u043b\u043b\u0430\u0440, \u0438 \u043e\u043d \u0434\u0435\u0440\u0436\u0438\u0442\u0441\u044f: \u043e\u0431\u043b\u0438\u0433\u0430\u0446\u0438\u0438 \u0421\u0428\u0410 \u043f\u043b\u0430\u0442\u044f\u0442 \u0431\u043e\u043b\u044c\u0448\u0435 5%, \u0434\u0435\u043d\u044c\u0433\u0438 \u0432 \u0434\u043e\u043b\u043b\u0430\u0440\u0430\u0445 \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u0434\u043e\u0440\u043e\u0433\u0438\u043c\u0438. \u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043a\u0443\u0440\u0441 \u043d\u0430 1 \u043e\u043a\u0442\u044f\u0431\u0440\u044f 83,56 \u0440\u0443\u0431\u043b\u044f \u0437\u0430 \u0434\u043e\u043b\u043b\u0430\u0440, \u043d\u0430 87 \u043a\u043e\u043f\u0435\u0435\u043a \u043d\u0438\u0436\u0435, \u0447\u0435\u043c \u0434\u043d\u0451\u043c \u0440\u0430\u043d\u044c\u0448\u0435. \u0420\u0443\u0431\u043b\u044c \u0443\u043a\u0440\u0435\u043f\u0438\u043b\u0441\u044f \u043f\u043e \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u043c \u043f\u0440\u0438\u0447\u0438\u043d\u0430\u043c: \u0432 \u043a\u043e\u043d\u0446\u0435 \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0451\u0440\u044b \u043f\u0440\u043e\u0434\u0430\u0432\u0430\u043b\u0438 \u0432\u0430\u043b\u044e\u0442\u043d\u0443\u044e \u0432\u044b\u0440\u0443\u0447\u043a\u0443, \u0430 \u0438\u043c\u043f\u043e\u0440\u0442\u0451\u0440\u044b \u043f\u0440\u0438\u0442\u0438\u0445\u043b\u0438 \u043f\u0435\u0440\u0435\u0434 \u043d\u0435\u0434\u0435\u043b\u044c\u043d\u044b\u043c\u0438 \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a\u0430\u043c\u0438 \u0432 \u041a\u0438\u0442\u0430\u0435."},{"id":"b006","kind":"paragraph","text":"\u0427\u0435\u0433\u043e \u043f\u043e\u043a\u0430 \u043d\u0435 \u0437\u043d\u0430\u0435\u043c: \u0434\u0430\u043d\u043d\u044b\u0435 \u0437\u0430 \u0430\u0432\u0433\u0443\u0441\u0442 \u043d\u0435 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u044e\u0442 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u044c\u0441\u043a\u0438\u0439 \u0440\u043e\u0441\u0442 \u0446\u0435\u043d \u043d\u0430 \u0442\u043e\u043f\u043b\u0438\u0432\u043e \u0438\u0437-\u0437\u0430 \u0432\u043e\u0439\u043d\u044b \u0441 \u0418\u0440\u0430\u043d\u043e\u043c, \u0438 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0439 \u043e\u0442\u0447\u0451\u0442 \u043c\u043e\u0436\u0435\u0442 \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440 \u043e \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u0438 \u0441\u0442\u0430\u0432\u043a\u0438. \u0414\u043b\u044f \u0442\u0435\u0445, \u043a\u0442\u043e \u0434\u0435\u0440\u0436\u0438\u0442 \u0434\u043e\u043b\u043b\u0430\u0440\u044b, \u0432\u044b\u0431\u043e\u0440 \u0442\u0430\u043a\u043e\u0439. \u041f\u0440\u043e\u0434\u0430\u0432\u0430\u0442\u044c \u0438\u0445 \u043d\u0430 \u043d\u043e\u0432\u043e\u0441\u0442\u0438 \u043e \u0437\u0430\u043c\u0435\u0434\u043b\u0435\u043d\u0438\u0438 \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u0438 \u0437\u043d\u0430\u0447\u0438\u0442 \u0432\u0435\u0440\u0438\u0442\u044c \u0446\u0438\u0444\u0440\u0435, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0432\u043e \u043c\u043d\u043e\u0433\u043e\u043c \u0441\u0434\u0435\u043b\u0430\u043b \u043f\u0435\u0440\u0435\u0441\u0447\u0451\u0442. \u041f\u043e\u043a\u0443\u043f\u0430\u0442\u044c \u0432 \u0440\u0430\u0441\u0447\u0451\u0442\u0435 \u043d\u0430 \u043d\u043e\u0432\u044b\u0435 \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044f \u0441\u0442\u0430\u0432\u043a\u0438 \u0437\u043d\u0430\u0447\u0438\u0442 \u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043d\u0430 \u043e\u0442\u0447\u0451\u0442, \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u0435\u0449\u0451 \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u0432\u0438\u0434\u0435\u043b."},{"id":"b007","kind":"heading","text":"\u041a\u0430\u043a\u0430\u044f \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u044f \u0432 \u0421\u0428\u0410 \u0432 \u0430\u0432\u0433\u0443\u0441\u0442\u0435 2026 \u0433\u043e\u0434\u0430?"},{"id":"b008","kind":"paragraph","text":"3,4% \u0437\u0430 \u0433\u043e\u0434 \u043f\u043e \u0438\u043d\u0434\u0435\u043a\u0441\u0443 PCE, \u0433\u043b\u0430\u0432\u043d\u043e\u043c\u0443 \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u0443 \u0424\u0420\u0421, \u043f\u0440\u0438 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0435 3,7%. \u0411\u0435\u0437 \u0435\u0434\u044b \u0438 \u044d\u043d\u0435\u0440\u0433\u0438\u0438 3% \u043f\u0440\u0438 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0435 3,3%. \u0426\u0435\u043b\u044c \u0424\u0420\u0421 2%."},{"id":"b009","kind":"heading","text":"\u041f\u043e\u0432\u044b\u0441\u0438\u0442 \u043b\u0438 \u0424\u0420\u0421 \u0441\u0442\u0430\u0432\u043a\u0443 \u0432 \u043e\u043a\u0442\u044f\u0431\u0440\u0435 2026 \u0433\u043e\u0434\u0430?"},{"id":"b010","kind":"paragraph","text":"\u041f\u043e\u0441\u043b\u0435 \u0434\u0430\u043d\u043d\u044b\u0445 \u0437\u0430 \u0430\u0432\u0433\u0443\u0441\u0442 \u0440\u044b\u043d\u043e\u043a \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442 \u0448\u0430\u043d\u0441 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0432 35% \u043f\u0440\u043e\u0442\u0438\u0432 45% \u043d\u0430\u043a\u0430\u043d\u0443\u043d\u0435. \u0421\u0435\u0439\u0447\u0430\u0441 \u0441\u0442\u0430\u0432\u043a\u0430 \u0424\u0420\u0421 3,75–4%, \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u043c\u0443\u0442 27–28 \u043e\u043a\u0442\u044f\u0431\u0440\u044f."},{"id":"b011","kind":"heading","text":"\u041f\u043e\u0447\u0435\u043c\u0443 \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u044f \u0432 \u0421\u0428\u0410 \u043e\u043a\u0430\u0437\u0430\u043b\u0430\u0441\u044c \u043d\u0438\u0436\u0435 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0430?"},{"id":"b012","kind":"paragraph","text":"\u041e\u0442\u0447\u0430\u0441\u0442\u0438 \u0438\u0437-\u0437\u0430 \u0441\u043c\u0435\u043d\u044b \u043c\u0435\u0442\u043e\u0434\u0438\u043a\u0438. \u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0438 \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u0430\u043b\u0438 \u0446\u0435\u043d\u044b \u043d\u0430 \u044e\u0440\u0438\u0434\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0443\u0441\u043b\u0443\u0433\u0438, \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b \u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u044f\u043c\u0438 \u043d\u0430\u0447\u0438\u043d\u0430\u044f \u0441 2021 \u0433\u043e\u0434\u0430. \u0418\u044e\u043b\u044c\u0441\u043a\u0430\u044f \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u044f \u0431\u0435\u0437 \u0435\u0434\u044b \u0438 \u044d\u043d\u0435\u0440\u0433\u0438\u0438 \u043f\u043e\u0441\u043b\u0435 \u043f\u0435\u0440\u0435\u0441\u0447\u0451\u0442\u0430 \u0441\u043d\u0438\u0437\u0438\u043b\u0430\u0441\u044c \u043d\u0430 0,36 \u043f\u0443\u043d\u043a\u0442\u0430, \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0441 3,3% \u0434\u043e 3%."}],"sources":[{"label":"Fed\'s preferred gauge showed core inflation at 3.0% in August","url":"https://www.cnbc.com/2026/09/30/feds-preferred-gauge-showed-core-inflation-at-3point0percent-in-august-much-lighter-than-expected.html"},{"label":"Minneapolis Fed President Neel Kashkari interview","url":"https://www.cnbc.com/2026/09/30/watch-minneapolis-fed-president-neel-kashkari.html"},{"label":"Good news in US inflation report boosts chances Fed won\'t hike rates","url":"https://www.theguardian.com/business/2026/sep/30/inflation-report-interest-rates-fed"},{"label":"PCE inflation eases to 3.4%, cooling the case for another Fed rate hike","url":"https://finance.yahoo.com/economy/policy/article/pce-inflation-eases-to-34--cooling-the-case-for-another-fed-rate-hike-125513195.html"},{"label":"PCE price index revised down","url":"https://finance.yahoo.com/economy/articles/pce-price-index-revised-down-123741659.html"},{"label":"Fed\'s preferred inflation metric came in cooler","url":"https://finance.yahoo.com/economy/articles/feds-preferred-inflation-metric-came-163426036.html"},{"label":"Fed\'s preferred inflation gauge declined","url":"https://finance.yahoo.com/economy/policy/articles/feds-preferred-inflation-gauge-declined-174601544.html"},{"label":"Fed preferred measure of inflation rose 3.4%","url":"https://finance.yahoo.com/economy/policy/articles/fed-preferred-measure-inflation-rose-124249351.html"},{"label":"Gold steady after softer inflation data","url":"https://finance.yahoo.com/markets/commodities/articles/gold-steady-softer-inflation-data-000816044.html"},{"label":"Fed\'s Kashkari says inflation goes beyond oil prices","url":"https://finance.yahoo.com/economy/policy/articles/feds-kashkari-says-inflation-goes-150738609.html"},{"label":"\u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043a\u0443\u0440\u0441 \u0434\u043e\u043b\u043b\u0430\u0440\u0430 \u043e\u043f\u0443\u0441\u0442\u0438\u043b\u0441\u044f \u043d\u0438\u0436\u0435 84 \u0440\u0443\u0431\u043b\u0435\u0439","url":"https://www.vedomosti.ru/finance/news/2026/09/30/1233185-kurs-opustilsya"},{"label":"\u041a\u0443\u0440\u0441 \u0434\u043e\u043b\u043b\u0430\u0440\u0430, \u0435\u0432\u0440\u043e \u0438 \u044e\u0430\u043d\u044f \u043d\u0430 1 \u043e\u043a\u0442\u044f\u0431\u0440\u044f 2026 \u0433\u043e\u0434\u0430: \u043f\u043e\u0447\u0435\u043c\u0443 \u0440\u0443\u0431\u043b\u044c \u0440\u0435\u0437\u043a\u043e \u0443\u043a\u0440\u0435\u043f\u0438\u043b\u0441\u044f","url":"https://www.vbr.ru/novosti/kursy-valyut/2026/09/30/kurs-valut-na-1-oktyabrya/"},{"label":"Meeting calendars and information","url":"https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm"}],"sourceBodySha256":"1145a94c8144e6d38a235e40e919942738f6348f62bad69c60f81ff17dc4c1a0"}')}}]);